/**
 * Booking blocks: the source of truth for which nights are booked.
 *
 * Each room document stores `blocks: StayBlock[]`. One block = one stay (one
 * guest party). Dates added in a single admin save become a new block with a
 * new id, so back-to-back guests stay separate even though their nights touch.
 *
 * The old `availability` map ({ "YYYY-MM-DD": true }) is still written as a
 * derived copy, so public pages keep working unchanged.
 *
 * Browser-safe: no Node imports. Ids are generated by the caller.
 */

export type StayBlock = {
  stayId: string;
  /** Booked nights, "YYYY-MM-DD", sorted ascending, contiguous */
  dates: string[];
  createdAt?: string | Date;
};

export type RoomDoc = {
  id: string;
  name?: string;
  availability?: Record<string, boolean> | null;
  blocks?: StayBlock[] | null;
};

export const VILLA_ID = "villa";
export const ROOM_IDS = ["villa", "family-room", "double-room"] as const;
/** Rooms inside the villa: booking the villa blocks these nights too */
export const VILLA_ROOMS = ["family-room", "double-room"] as const;
export const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

export function addDays(date: string, days: number): string {
  const d = new Date(`${date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** Split dates into runs of consecutive nights */
export function groupConsecutive(dates: Iterable<string>): string[][] {
  const sorted = [...new Set(dates)].sort();
  const groups: string[][] = [];
  for (const date of sorted) {
    const last = groups[groups.length - 1];
    if (last && addDays(last[last.length - 1], 1) === date) last.push(date);
    else groups.push([date]);
  }
  return groups;
}

/** Id used for blocks converted from the legacy map; matches the old stay key */
export const legacyStayId = (roomId: string, checkIn: string) => `${roomId}_${checkIn}`;

const bookedInMap = (map: RoomDoc["availability"]) =>
  Object.entries(map || {})
    .filter(([d, b]) => b === true && DATE_RE.test(d))
    .map(([d]) => d);

/**
 * Blocks for every room. Rooms saved before blocks existed are converted from
 * their availability map: consecutive runs become blocks, keeping the legacy
 * `${roomId}_${checkIn}` id so ID photos uploaded under it stay linked. The
 * legacy admin copied villa nights into both rooms, so those are dropped from
 * the rooms (they belong to the villa block).
 */
export function resolveBlocks(rooms: RoomDoc[]): Record<string, StayBlock[]> {
  const out: Record<string, StayBlock[]> = {};
  const convert = (r: RoomDoc, exclude: Set<string>) =>
    groupConsecutive(bookedInMap(r.availability).filter((d) => !exclude.has(d))).map((dates) => ({
      stayId: legacyStayId(r.id, dates[0]),
      dates,
    }));

  const villa = rooms.find((r) => r.id === VILLA_ID);
  if (villa) out[VILLA_ID] = Array.isArray(villa.blocks) ? normalise(villa.blocks) : convert(villa, new Set());
  const villaNights = ownDates(out[VILLA_ID] ?? []);

  for (const r of rooms) {
    if (r.id === VILLA_ID) continue;
    out[r.id] = Array.isArray(r.blocks) ? normalise(r.blocks) : convert(r, villaNights);
  }
  return out;
}

/** Defensive clean-up of stored blocks: valid dates only, sorted, no empties */
function normalise(blocks: StayBlock[]): StayBlock[] {
  return blocks
    .map((b) => ({ ...b, dates: [...new Set((b.dates || []).filter((d) => DATE_RE.test(d)))].sort() }))
    .filter((b) => b.stayId && b.dates.length > 0)
    .sort((a, b) => a.dates[0].localeCompare(b.dates[0]));
}

export function ownDates(blocks: StayBlock[]): Set<string> {
  return new Set(blocks.flatMap((b) => b.dates));
}

/**
 * Public "booked nights" map per room, the same shape the site always used:
 * villa = its own blocks; each room = its own blocks + the villa's.
 */
export function availabilityMaps(byRoom: Record<string, StayBlock[]>): Record<string, Record<string, true>> {
  const villaNights = ownDates(byRoom[VILLA_ID] ?? []);
  const out: Record<string, Record<string, true>> = {};
  for (const [id, blocks] of Object.entries(byRoom)) {
    const nights = ownDates(blocks);
    if (id !== VILLA_ID) villaNights.forEach((d) => nights.add(d));
    out[id] = Object.fromEntries([...nights].sort().map((d) => [d, true as const]));
  }
  return out;
}

/** Thrown when an extension can't be applied (bad id, gap, or clash) */
export class BlockError extends Error {}

/**
 * Apply one save: `finalDates` is the complete set of nights the room should
 * own afterwards.
 *  - Removed nights are taken out of their block. A block that becomes empty
 *    is deleted; one split in two keeps its id on the earlier part (so its ID
 *    photos stay with it) and the later part gets a new id.
 *  - `extensions` ({ stayId: nights }) adds nights to an EXISTING block,
 *    before or after it, keeping its id (and ID photos). The extended stay
 *    must remain one continuous run.
 *  - Any other added nights become NEW blocks, one per consecutive run, even
 *    when they touch an existing block. That keeps back-to-back guests separate.
 */
export function applyBookedDates(
  prev: StayBlock[],
  finalDates: Iterable<string>,
  newId: () => string,
  now: Date = new Date(),
  extensions: Record<string, string[]> = {}
): StayBlock[] {
  const final = new Set(finalDates);
  const existing = ownDates(prev);

  // Validate extensions before changing anything
  const extended = new Set<string>();
  for (const [stayId, nights] of Object.entries(extensions)) {
    if (!nights.length) continue;
    if (!prev.some((b) => b.stayId === stayId)) throw new BlockError(`Stay ${stayId} no longer exists`);
    for (const d of nights) {
      if (!DATE_RE.test(d)) throw new BlockError(`Invalid date ${d}`);
      if (existing.has(d)) throw new BlockError(`${d} is already booked by another stay`);
      if (!final.has(d)) throw new BlockError(`${d} isn't booked in this save`);
      if (extended.has(d)) throw new BlockError(`${d} is used by two extensions`);
      extended.add(d);
    }
  }

  const next: StayBlock[] = [];
  for (const block of prev) {
    const kept = block.dates.filter((d) => final.has(d));
    const extra = extensions[block.stayId] ?? [];
    if (extra.length) {
      // An extended stay keeps its id and must stay one continuous run
      const runs = groupConsecutive([...kept, ...extra]);
      if (runs.length !== 1) {
        throw new BlockError("An extension must connect directly to the start or end of its stay");
      }
      next.push({ ...block, dates: runs[0] });
      continue;
    }
    groupConsecutive(kept).forEach((dates, i) =>
      next.push(i === 0 ? { ...block, dates } : { stayId: newId(), dates, createdAt: now })
    );
  }

  const added = [...final].filter((d) => !existing.has(d) && !extended.has(d));
  for (const dates of groupConsecutive(added)) next.push({ stayId: newId(), dates, createdAt: now });

  return next.sort((a, b) => a.dates[0].localeCompare(b.dates[0]));
}
